export function RoleChip({
  role,
  selected,
  disabled,
  onClick,
}: {
  role: string;
  selected: boolean;
  disabled: boolean;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      className="py-2 px-4 max-w-full rounded-full [border:1px_dashed_var(--settings-strong)] text-[13.5px] font-semibold text-[var(--settings-muted)] [background:transparent] cursor-pointer wrap-anywhere [&[aria-pressed='true']]:border-solid [&[aria-pressed='true']]:border-[var(--appearance-border,_var(--color-settings-settings-purple-21))] [&[aria-pressed='true']]:[background:var(--appearance-wash,_var(--color-settings-settings-border-17))] [&[aria-pressed='true']]:text-[var(--settings-text)]"
      aria-pressed={selected}
      disabled={disabled}
      onClick={onClick}
    >
      {role}
      {selected && (
        <span className="text-[var(--settings-pink)]" aria-hidden="true">
          {" "}
          ✓
        </span>
      )}
    </button>
  );
}
